","import React, { useState, useEffect } from "react";
import "./Navigation.css";

interface NavProps {
 currentView: string;
 navigateToView: (view: string, id?: string | null) => void;
}

const NAV_ITEMS = [
 { view: "home", label: "Home", adminOnly: false },
 { view: "book-ticket", label: "Book Ticket", adminOnly: false },
 { view: "student-pass", label: "Student Pass", adminOnly: false },
 { view: "my-tickets", label: "My Tickets", adminOnly: false },
 { view: "my-student-passes", label: "My Passes", adminOnly: false },
 { view: "payment-history", label: "Payment History", adminOnly: false },
 { view: "my-complaints", label: "My Complaints", adminOnly: false },
 { view: "complaint", label: "Complaint", adminOnly: false },
 { view: "admin-dashboard", label: "Admin Dashboard", adminOnly: true }
];

export default function Navigation({ currentView, navigateToView }: NavProps) {
 const [isAdmin, setIsAdmin] = useState(false);

 useEffect(() => {
 async function checkAdminRole() {
 try {
 const headers = {
 "Content-Type": "application/json",
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck
 };
 // Check for Metro Admin role
 const res = await fetch(
 "/api/now/table/sys_user_has_role?sysparm_query=user=javascript:gs.getUserID()^role.name=x_1877508_metro_0.MetromTicket Metro Admin&sysparm_limit=1",
 { headers }
 );
 const data = await res.json();
 if (data.result && data.result.length > 0) {
 setIsAdmin(true);
 return;
 }
 // Fallback: check for platform admin role
 const adminRes = await fetch(
 "/api/now/table/sys_user_has_role?sysparm_query=user=javascript:gs.getUserID()^role.name=admin&sysparm_limit=1",
 { headers }
 );
 const adminData = await adminRes.json();
 setIsAdmin(adminData.result && adminData.result.length > 0);
 } catch {
 setIsAdmin(false);
 }
 }
 checkAdminRole();
 }, []);

 const visibleItems = NAV_ITEMS.filter(item => !item.adminOnly || isAdmin);

 return (
 <nav className="metro-nav">
 <div className="metro-nav__brand">Metro Ticket Booking</div>
 <ul className="metro-nav__list">
 {visibleItems.map(item => (
 <li
 key={item.view}
 className={`metro-nav__item ${
 currentView === item.view ? "metro-nav__item--active" : ""
 }`}
 >
 <a
 className="metro-nav__link"
 href={`?view=${item.view}`}
 onClick={e => {
 e.preventDefault();
 navigateToView(item.view);
 }}
 >
 {item.label}
 </a>
 </li>
 ))}
 </ul>
 </nav>
 );
}
","const BASE_URL = "/api/now/table";

function getHeaders() {
 return {
 "Content-Type": "application/json",
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck
 };
}

function buildUrl(table: string, sysId?: string): string {
 const path = sysId ? `${BASE_URL}/${table}/${sysId}` : `${BASE_URL}/${table}`;
 const url = new URL(path, window.location.origin);
 url.searchParams.set("sysparm_display_value", "all");
 return url.toString();
}

async function request(url: string, options?: RequestInit) {
 const res = await fetch(url, { headers: getHeaders(), ...options });
 if (!res.ok) throw new Error(`API error: ${res.status}`);
 return res.json();
}

export const MetroService = {
 async list(table: string, query?: string, limit?: number) {
 const url = new URL(`${BASE_URL}/${table}`, window.location.origin);
 url.searchParams.set("sysparm_display_value", "all");
 if (query) url.searchParams.set("sysparm_query", query);
 if (limit) url.searchParams.set("sysparm_limit", String(limit));
 const data = await request(url.toString());
 return data.result || [];
 },

 async get(table: string, sysId: string) {
 const data = await request(buildUrl(table, sysId));
 return data.result;
 },

 async create(table: string, body: Record<string, any>) {
 const data = await request(buildUrl(table), {
 method: "POST",
 body: JSON.stringify(body)
 });
 return data.result;
 },

 async update(table: string, sysId: string, body: Record<string, any>) {
 const data = await request(buildUrl(table, sysId), {
 method: "PATCH",
 body: JSON.stringify(body)
 });
 return data.result;
 },

 async getStations() {
 return this.list("x_1877508_metro_0_metro_stations", "active=true^ORDERBYstation_name");
 },

 async getFare(sourceId: string, destId: string) {
 const records = await this.list(
 "x_1877508_metro_0_metro_fare_matrix",
 `source_station=${sourceId}^destination_station=${destId}^active=true`
 );
 return records.length > 0 ? records[0] : null;
 },

 async getPassengerByUser() {
 const records = await this.list(
 "x_1877508_metro_0_metro_passenger",
 "user=javascript:gs.getUserID()"
 );
 return records.length > 0 ? records[0] : null;
 }
};
