","import React, { useState, useEffect } from "react";
import { MetroService } from "../services/MetroService";
import { display, value } from "../utils/fields";
import "./Payment.css";

interface PaymentProps {
 navigateToView: (view: string, id?: string | null, extra?: Record<string, string>) => void;
 referenceId: string | null;
 paymentFor: string | null;
}

/** Strip any existing currency symbols/letters and return clean numeric string */
function formatAmount(rawValue: string): string {
 if (!rawValue) return "0.00";
 // Remove any non-numeric characters except dot and minus
 const cleaned = rawValue.replace(/[^0-9.\-]/g, "");
 const num = parseFloat(cleaned);
 if (isNaN(num)) return "0.00";
 return num.toFixed(2);
}

export default function Payment({ navigateToView, referenceId, paymentFor }: PaymentProps) {
 const [record, setRecord] = useState<any>(null);
 const [loading, setLoading] = useState(true);
 const [paymentMethod, setPaymentMethod] = useState("upi");
 const [processing, setProcessing] = useState(false);
 const [error, setError] = useState("");

 useEffect(() => {
 async function loadRecord() {
 if (!referenceId || !paymentFor) {
 setLoading(false);
 return;
 }
 try {
 const table = paymentFor === "booking"
 ? "x_1877508_metro_0_metro_booking"
 : "x_1877508_metro_0_metro_student_pass";
 const data = await MetroService.get(table, referenceId);
 setRecord(data);
 } catch (e) {
 console.error("Failed to load record", e);
 setError("Failed to load payment details.");
 } finally {
 setLoading(false);
 }
 }
 loadRecord();
 }, [referenceId, paymentFor]);

 async function handlePayment(e: React.FormEvent) {
 e.preventDefault();
 if (!record || !referenceId) return;
 setProcessing(true);
 setError("");

 try {
 const amount = paymentFor === "booking"
 ? value(record.fare_amount)
 : value(record.pass_amount);

 const paymentBody: Record<string, any> = {
 payment_method: paymentMethod,
 amount: amount,
 transaction_status: "success",
 transaction_reference: "TXN" + Date.now()
 };

 if (paymentFor === "booking") {
 paymentBody.booking = referenceId;
 } else {
 paymentBody.student_pass = referenceId;
 }

 await MetroService.create("x_1877508_metro_0_metro_payment", paymentBody);

 if (paymentFor === "booking") {
 await MetroService.update("x_1877508_metro_0_metro_booking", referenceId, {
 booking_status: "confirmed",
 payment_status: "paid"
 });
 navigateToView("my-tickets");
 } else {
 await MetroService.update("x_1877508_metro_0_metro_student_pass", referenceId, {
 pass_status: "active",
 payment_status: "paid"
 });
 navigateToView("my-student-passes");
 }
 } catch (err) {
 console.error("Payment failed", err);
 setError("Payment processing failed. Please try again.");
 setProcessing(false);
 }
 }

 if (loading) {
 return (
 <div className="metro-payment">
 <h1 className="metro-payment__title">Processing Payment</h1>
 <p>Loading payment details...</p>
 </div>
 );
 }

 if (!record || !referenceId || !paymentFor) {
 return (
 <div className="metro-payment">
 <h1 className="metro-payment__title">Payment</h1>
 <p className="metro-payment__error">No payment reference found. Please book a ticket or apply for a pass first.</p>
 <button className="metro-payment__btn" onClick={() => navigateToView("home")}>Back to Home</button>
 </div>
 );
 }

 // Use value() to get raw numeric amount, then format cleanly
 const rawAmount = paymentFor === "booking" ? value(record.fare_amount) : value(record.pass_amount);
 const amount = formatAmount(rawAmount);
 const refNumber = paymentFor === "booking"
 ? (display(record.booking_number) || display(record.number))
 : (display(record.pass_number) || display(record.number));

 return (
 <div className="metro-payment">
 <h1 className="metro-payment__title">Complete Payment</h1>

 <div className="metro-payment__summary">
 <h3 className="metro-payment__summary-title">Payment Summary</h3>
 <div className="metro-payment__detail">
 <span>Reference:</span>
 <span className="metro-payment__ref">{refNumber}</span>
 </div>
 <div className="metro-payment__detail">
 <span>Type:</span>
 <span>{paymentFor === "booking" ? "Metro Ticket Booking" : "Student Pass"}</span>
 </div>
 {paymentFor === "booking" && (
 <>
 <div className="metro-payment__detail">
 <span>Route:</span>
 <span>{display(record.source_station)} → {display(record.destination_station)}</span>
 </div>
 <div className="metro-payment__detail">
 <span>Journey Date:</span>
 <span>{display(record.journey_date)}</span>
 </div>
 <div className="metro-payment__detail">
 <span>Passengers:</span>
 <span>{display(record.passenger_count)}</span>
 </div>
 </>
 )}
 {paymentFor === "pass" && (
 <>
 <div className="metro-payment__detail">
 <span>Route:</span>
 <span>{display(record.source_station)} → {display(record.destination_station)}</span>
 </div>
 <div className="metro-payment__detail">
 <span>Pass Type:</span>
 <span>{display(record.pass_type)}</span>
 </div>
 </>
 )}
 <div className="metro-payment__detail metro-payment__detail--total">
 <span>Amount to Pay:</span>
 <span className="metro-payment__amount">₹{amount}</span>
 </div>
 </div>

 <form className="metro-payment__form" onSubmit={handlePayment}>
 {error && <div className="metro-payment__error">{error}</div>}

 <label className="metro-payment__label">
 Select Payment Method
 <div className="metro-payment__methods">
 <label className={`metro-payment__method ${paymentMethod === "upi" ? "metro-payment__method--selected" : ""}`}>
 <input type="radio" name="method" value="upi" checked={paymentMethod === "upi"} onChange={e => setPaymentMethod(e.target.value)} />
 <span>📱 UPI</span>
 </label>
 <label className={`metro-payment__method ${paymentMethod === "card" ? "metro-payment__method--selected" : ""}`}>
 <input type="radio" name="method" value="card" checked={paymentMethod === "card"} onChange={e => setPaymentMethod(e.target.value)} />
 <span>💳 Card</span>
 </label>
 <label className={`metro-payment__method ${paymentMethod === "net_banking" ? "metro-payment__method--selected" : ""}`}>
 <input type="radio" name="method" value="net_banking" checked={paymentMethod === "net_banking"} onChange={e => setPaymentMethod(e.target.value)} />
 <span>🏦 Net Banking</span>
 </label>
 </div>
 </label>

 <button className="metro-payment__btn metro-payment__btn--pay" type="submit" disabled={processing}>
 {processing ? "Processing Payment..." : `Pay ₹${amount}`}
 </button>
 </form>
 </div>
 );
}
","import React, { useState, useEffect } from "react";
import { MetroService } from "../services/MetroService";
import { display, value } from "../utils/fields";
import "./PassDetails.css";

interface PassDetailsProps {
 navigateToView: (view: string, id?: string) => void;
}

export default function PassDetails({ navigateToView }: PassDetailsProps) {
 const [passes, setPasses] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [message, setMessage] = useState("");

 async function fetchPasses() {
 try {
 const data = await MetroService.list(
 "x_1877508_metro_0_metro_student_pass",
 "ORDERBYDESCsys_created_on",
 20
 );
 setPasses(data);
 } catch (e) {
 console.error("Failed to fetch passes", e);
 } finally {
 setLoading(false);
 }
 }

 useEffect(() => { fetchPasses(); }, []);

 async function handleRenew(pass: any) {
 const today = new Date();
 const validFrom = today.toISOString().split("T")[0];
 const duration = value(pass.pass_type) === "quarterly" ? 90 : 30;
 const until = new Date(today.getTime() + duration * 86400000);
 const validUntil = until.toISOString().split("T")[0];

 try {
 await MetroService.create("x_1877508_metro_0_metro_student_pass", {
 student: value(pass.student),
 source_station: value(pass.source_station),
 destination_station: value(pass.destination_station),
 pass_type: value(pass.pass_type),
 valid_from: validFrom,
 valid_until: validUntil,
 payment_status: "pending",
 pass_status: "draft"
 });
 setMessage("Renewal request created successfully.");
 await fetchPasses();
 } catch (e) {
 setMessage("Failed to create renewal request.");
 }
 }

 if (loading) return <div className="metro-pass-details"><p>Loading passes...</p></div>;

 return (
 <div className="metro-pass-details">
 <h1 className="metro-pass-details__title">Student Passes</h1>
 {message && <p className="metro-pass-details__message">{message}</p>}
 {passes.length === 0 && <p>No student passes found.</p>}
 <div className="metro-pass-details__grid">
 {passes.map((pass) => (
 <div key={pass.sys_id.value} className="metro-pass-details__card">
 <div className="metro-pass-details__row"><span>Pass Number</span><span>{display(pass.pass_number) || display(pass.number)}</span></div>
 <div className="metro-pass-details__row"><span>Student</span><span>{display(pass.student)}</span></div>
 <div className="metro-pass-details__row"><span>Pass Type</span><span>{display(pass.pass_type)}</span></div>
 <div className="metro-pass-details__row"><span>Source</span><span>{display(pass.source_station)}</span></div>
 <div className="metro-pass-details__row"><span>Destination</span><span>{display(pass.destination_station)}</span></div>
 <div className="metro-pass-details__row"><span>Valid From</span><span>{display(pass.valid_from)}</span></div>
 <div className="metro-pass-details__row"><span>Valid Until</span><span>{display(pass.valid_until)}</span></div>
 <div className="metro-pass-details__row"><span>Amount</span><span>₹{display(pass.pass_amount)}</span></div>
 <div className="metro-pass-details__row"><span>Payment</span><span>{display(pass.payment_status)}</span></div>
 <div className="metro-pass-details__row"><span>Status</span><span>{display(pass.pass_status)}</span></div>
 <div className="metro-pass-details__row"><span>QR Ticket</span><span>{display(pass.qr_ticket)}</span></div>
 <button className="metro-pass-details__renew" onClick={() => handleRenew(pass)}>Renew Pass</button>
 </div>
 ))}
 </div>
 </div>
 );
}
