 activePassCount: number;
 pendingVerifications: number;
 complaintsRaised: number;
 resolvedComplaints: number;
 qrTickets: number;
}

interface AdminKPIsProps {
 data: KPIData;
 navigateToView: (view: string, id?: string | null) => void;
}

const KPI_ITEMS = [
 { key: "totalBookings", label: "Total Bookings", route: "admin-bookings", color: "#1a237e", icon: "🎫" },
 { key: "totalPayments", label: "Total Payments", route: "admin-payments", color: "#4caf50", icon: "💰" },
 { key: "totalRevenue", label: "Total Revenue", route: "admin-revenue", color: "#ff9800", prefix: "₹", icon: "📊" },
 { key: "activePassCount", label: "Active Passes", route: "admin-active-passes", color: "#2196f3", icon: "🎓" },
 { key: "pendingVerifications", label: "Pending Verifications", route: "admin-student-verifications", color: "#9c27b0", icon: "⏳" },
 { key: "complaintsRaised", label: "Complaints Raised", route: "admin-complaints", color: "#795548", icon: "📝" },
 { key: "resolvedComplaints", label: "Resolved Complaints", route: "admin-complaints", color: "#4caf50", icon: "✅" },
 { key: "qrTickets", label: "QR Tickets", route: "admin-qr-tickets", color: "#00bcd4", icon: "📱" }
];

export default function AdminKPIs({ data, navigateToView }: AdminKPIsProps) {
 return (
 <div className="metro-admin__kpis">
 {KPI_ITEMS.map(item => (
 <div
 key={item.key}
 className="metro-admin__kpi-card metro-admin__kpi-card--clickable"
 style={{ borderLeftColor: item.color, cursor: "pointer" }}
 onClick={() => navigateToView(item.route)}
 role="button"
 tabIndex={0}
 onKeyDown={e => e.key === "Enter" && navigateToView(item.route)}
 >
 <span className="metro-admin__kpi-icon">{item.icon}</span>
 <span className="metro-admin__kpi-value">
 {item.prefix || ""}{(data as any)[item.key]}
 </span>
 <span className="metro-admin__kpi-label">{item.label}</span>
 </div>
 ))}
 </div>
 );
}
","import React, { useState, useEffect, useCallback } from "react";
import { MetroService } from "../services/MetroService";
import { value } from "../utils/fields";
import AdminKPIs from "./AdminKPIs";
import "./AdminDashboard.css";

interface AdminDashboardProps {
 navigateToView: (view: string, id?: string | null) => void;
}

export default function AdminDashboard({ navigateToView }: AdminDashboardProps) {
 const [kpiData, setKpiData] = useState<any>(null);
 const [loading, setLoading] = useState(true);

 const fetchData = useCallback(async () => {
 try {
 const [bk, py, cp, ps, vr, qr] = await Promise.all([
 MetroService.list("x_1877508_metro_0_metro_booking"),
 MetroService.list("x_1877508_metro_0_metro_payment"),
 MetroService.list("x_1877508_metro_0_metro_complaint"),
 MetroService.list("x_1877508_metro_0_metro_student_pass", "pass_status=active"),
 MetroService.list("x_1877508_metro_0_metro_student_profile", "verification_status=pending"),
 MetroService.list("x_1877508_metro_0_metro_qr_ticket")
 ]);
 const totalRevenue = py.reduce((s: number, p: any) => s + (parseFloat(value(p.amount)) || 0), 0);

 // Resolved Complaints: only status = resolved
 const resolvedComplaints = cp.filter((c: any) => {
 const status = (value(c.status) || "").toLowerCase();
 return status === "resolved";
 }).length;

 // Complaints Raised: Total count of all complaints
 const complaintsRaised = cp.length;

 setKpiData({
 totalBookings: bk.length,
 totalPayments: py.length,
 totalRevenue,
 activePassCount: ps.length,
 pendingVerifications: vr.length,
 complaintsRaised,
 resolvedComplaints,
 qrTickets: qr.length
 });
 } catch (e) { console.error("Dashboard load failed", e); }
 finally { setLoading(false); }
 }, []);

 useEffect(() => { fetchData(); }, [fetchData]);

 if (loading) return <div className="metro-admin"><p>Loading dashboard...</p></div>;

 return (
 <div className="metro-admin">
 <h1 className="metro-admin__title">Admin Dashboard</h1>
 <p className="metro-admin__subtitle">Click any card to manage records</p>
 {kpiData && <AdminKPIs data={kpiData} navigateToView={navigateToView} />}
 </div>
 );
}
","import React, { useState, useEffect } from "react";
import { MetroService } from "../services/MetroService";
import { display, value } from "../utils/fields";
import "./MyStudentPasses.css";

interface Props {
 navigateToView: (view: string, id?: string) => void;
}

/** Strip any existing currency symbols/letters and return clean numeric string */
function formatAmount(rawValue: string): string {
 if (!rawValue) return "0.00";
 const cleaned = rawValue.replace(/[^0-9.\-]/g, "");
 const num = parseFloat(cleaned);
 if (isNaN(num)) return "0.00";
 return num.toFixed(2);
}

export default function MyStudentPasses({ navigateToView }: Props) {
 const [passes, setPasses] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 async function fetch() {
 try {
 const data = await MetroService.list(
 "x_1877508_metro_0_metro_student_pass", "ORDERBYDESCsys_created_on", 20
 );
 setPasses(data);
 } catch (e) { console.error("Failed to fetch passes", e); }
 finally { setLoading(false); }
 }
 fetch();
 }, []);

 if (loading) return <div className="metro-passes"><p>Loading passes...</p></div>;

 if (passes.length === 0) {
 return (
 <div className="metro-passes">
 <h1 className="metro-passes__title">My Student Passes</h1>
 <p className="metro-passes__empty">No student passes found.</p>
 </div>
 );
 }

 return (
 <div className="metro-passes">
 <h1 className="metro-passes__title">My Student Passes</h1>
 <div className="metro-passes__list">
 {passes.map(p => (
