function formatAmount(raw: string): string {
 if (!raw) return "0.00";
 const num = parseFloat(raw.replace(/[^0-9.\-]/g, ""));
 return isNaN(num) ? "0.00" : num.toFixed(2);
}

function statusBadge(status: string): string {
 const s = status.toLowerCase();
 if (s === "confirmed" || s === "paid") return "admin-list-page__card-badge--green";
 if (s === "pending" || s === "pending_payment") return "admin-list-page__card-badge--orange";
 if (s === "cancelled" || s === "failed") return "admin-list-page__card-badge--red";
 return "admin-list-page__card-badge--blue";
}

