 .then(data => {
 setPayments(data);
 const total = data.reduce((sum: number, p: any) => sum + (parseFloat(value(p.amount)) || 0), 0);
 setTotalRevenue(total);
 })
 .catch(e => console.error("Failed to fetch revenue data", e))
 .finally(() => setLoading(false));
