 margin-bottom: 16px;
 padding: 0;
}

.metro-admin-cpl__title {
 font-size: 24px;
 color: #1a237e;
 margin: 0 0 16px;
}

.metro-admin-cpl__msg--success {
 background: #e8f5e9;
 color: #2e7d32;
 padding: 10px 14px;
 border-radius: 4px;
 margin-bottom: 12px;
 font-size: 13px;
}

.metro-admin-cpl__msg--error {
 background: #ffebee;
 color: #c62828;
 padding: 10px 14px;
 border-radius: 4px;
 margin-bottom: 12px;
 font-size: 13px;
}

.metro-admin-cpl__list {
 display: flex;
 flex-direction: column;
 gap: 10px;
}

.metro-admin-cpl__card {
 background: #ffffff;
 border-radius: 8px;
 padding: 14px;
 box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.metro-admin-cpl__row {
 display: flex;
 justify-content: space-between;
 font-size: 13px;
 padding: 3px 0;
 border-bottom: 1px solid #f0f0f0;
}

.metro-admin-cpl__row span:first-child {
 color: #666666;
 font-weight: 600;
}

.metro-admin-cpl__row span:last-child {
 color: #333333;
}

.metro-admin-cpl__action {
 display: flex;
 align-items: center;
 gap: 8px;
 margin-top: 10px;
 font-size: 13px;
}

.metro-admin-cpl__action select {
 padding: 4px 8px;
 border-radius: 4px;
 border: 1px solid #cccccc;
 font-size: 13px;
}
",".metro-app {
 font-family: var(--now-font-family, "Lato", sans-serif);
 min-height: 100vh;
 display: flex;
 flex-direction: column;
 background-color: rgb(var(--now-color--background-primary, 255, 255, 255));
 color: rgb(var(--now-color--text-primary, 41, 41, 41));
 overflow-x: hidden;
}

.metro-app__content {
 flex: 1;
 padding: 16px 24px;
 max-width: 1200px;
 margin: 0 auto;
 width: 100%;
 box-sizing: border-box;
}

@media (max-width: 480px) {
 .metro-app__content {
 padding: 12px 16px;
 }
}
